"""Generate concise supervisor handoff from measured follow-up tables."""
from pathlib import Path
import json
import pandas as pd

ROOT=Path(__file__).resolve().parents[1]

def main():
    out=ROOT/'outputs/replay_followup_report';s=pd.read_csv(out/'type_summary.csv');p=pd.read_csv(out/'paired_intervals.csv');families=pd.read_csv(out/'family_summary.csv')
    assert len(s)==28
    def value(env,method,metric):return float(s[(s.environment==env)&(s.method==method)].iloc[0][metric+'_mean'])
    def interval(env,left,right,metric,order='averaged'):
        r=p[(p.contrast==f'{env} {left}_minus_{right}')&(p.metric==metric)&(p.order==order)].iloc[0]
        return f"{100*r.mean_difference:+.2f} [{100*r.ci95_low:.2f}, {100*r.ci95_high:.2f}]"
    lines=['# Supervisor follow-up: completed deliverables','','The 7 October requests are complete. New training: **84 calibration-only trials + 420 evaluation runs**. The combined evidence contains **840 evaluated cases**, including the unchanged original 420. No training labels were merged.','','## 1. Class-balanced replay at memory 60','','| Environment | Method | Old-type accuracy | Forgetting | Rare-type recall | Worst-client macro recall |','|---|---|---:|---:|---:|---:|']
    for env in ['federated','centralized']:
        for method in ['uniform_60','class_balanced_60','protected_60']:
            vals=[100*value(env,method,m) for m in ['old_task_accuracy','forgetting','rare_attack_recall','worst_client_macro_recall']]
            lines.append('| '+' | '.join([env,method]+[f'{v:.2f}' for v in vals])+' |')
    lines+=['','Protected minus class-balanced, percentage points with paired-seed 95% intervals:']
    for env in ['federated','centralized']:
        lines.append(f"- {env}: old accuracy {interval(env,'protected_60','class_balanced_60','old_task_accuracy')}; rare recall {interval(env,'protected_60','class_balanced_60','rare_attack_recall')}.")
    lines+=['','The baseline changes the contribution: protected replay is not the strongest tested method for overall old-type retention at memory 60. It trades some retention and station-wide macro recall for greater rare-type recall relative to class-balanced replay. Do not claim that protected replay dominates all equal-budget alternatives.','','## 2. Joint confusion and fit quality','','See `outputs/joint_diagnostics/JOINT_CONFUSION_REPORT.md` and both PNG/PDF matrices. Several scan types are repeatedly confused; tiny ICMP classes also have notable errors. Final-model all-type accuracy is 57.21% federated / 59.56% centralized, compared with fitting accuracy 57.61% / 60.11%. Low fitting accuracy demonstrates difficulty under the current model/training setup too; confusion does not prove irreducible label ambiguity. The exact transformed-vector audit finds virtually no cross-type identical vectors.','','The near-99% pilot figures apply to selected easier tasks, not all-type joint accuracy. Prespecified task-family reporting is included alongside type results without selecting new merges from evaluation confusion. Family all-sample accuracy from summed probabilities is:']
    for env in ['federated','centralized']:
        r=families[(families.environment==env)&(families.method=='joint')].iloc[0]
        lines.append(f'- {env}: {100*r.accuracy:.2f}% (mapped winning-type family accuracy {100*r.mapped_type_prediction_accuracy:.2f}%).')
    lines+=['','## 3. Memory-size sweep','','The size is per federated client; centralized budgets are five times this size. These are separate calibration-selected procedures.','','| Environment | Memory/client | Uniform old accuracy / rare recall | Balanced old accuracy / rare recall | Protected old accuracy / rare recall |','|---|---:|---|---|---|']
    for env in ['federated','centralized']:
        for n in [60,120,300]:
            vals=[f'{100*value(env,f"{m}_{n}","old_task_accuracy"):.2f} / {100*value(env,f"{m}_{n}","rare_attack_recall"):.2f}' for m in ['uniform','class_balanced','protected']]
            lines.append('| '+' | '.join([env,str(n)]+vals)+' |')
    lines+=['','| Environment | Capacity | Protected−uniform old accuracy | Protected−balanced old accuracy | Protected−balanced rare recall |','|---|---:|---|---|---|']
    for env in ['federated','centralized']:
        for n in [60,120,300]:lines.append(f"| {env} | {n} | {interval(env,f'protected_{n}',f'uniform_{n}','old_task_accuracy')} | {interval(env,f'protected_{n}',f'class_balanced_{n}','old_task_accuracy')} | {interval(env,f'protected_{n}',f'class_balanced_{n}','rare_attack_recall')} |")
    lines+=['','Intervals, not only point estimates, determine whether a difference persists at larger memory. Effects can differ across capacities and metrics; memory growth does not automatically establish disappearance or monotonic improvement.','','Protected-300 federated old-type accuracy (61.75%) exceeds the original joint reference (55.39%). Joint therefore is an empirical offline reference, not a demonstrated upper bound. Its five all-data rounds and continual training/rehearsal have different optimization and repeated-benign exposures, as recorded in the original protocol. A strictly optimized upper-bound claim would require a separately specified calibration-only training-budget study.','','## 4. EWC and A-GEM','','| Environment | Method | Old accuracy | Forgetting | Rare recall | Worst-client macro recall |','|---|---|---:|---:|---:|---:|']
    for env in ['federated','centralized']:
        for m in ['ewc','agem']:
            lines.append('| '+' | '.join([env,m]+[f'{100*value(env,m,k):.2f}' for k in ['old_task_accuracy','forgetting','rare_attack_recall','worst_client_macro_recall']])+' |')
    lines+=['','| Environment | Protected−method | Metric | Paired difference [95% interval] |','|---|---|---|---|']
    for env in ['federated','centralized']:
        for m in ['ewc','agem']:
            for k in ['old_task_accuracy','forgetting','rare_attack_recall','worst_client_macro_recall']:lines.append(f"| {env} | {m} | {k} | {interval(env,'protected_60',m,k)} |")
    lines+=['','## 5. Attack-order consistency','','Every order-specific comparison at every memory is in `paired_intervals.csv` and `FOLLOWUP_RESULTS.md`. The following focuses on the original capacity. Positive old accuracy/recall is favorable; negative forgetting is favorable.','','| Environment | Order | Protected−uniform old accuracy | Protected−balanced old accuracy | Protected−uniform rare recall | Protected−balanced rare recall |','|---|---|---|---|---|---|']
    for env in ['federated','centralized']:
        for order in ['order_1','order_2','order_3']:
            vals=[interval(env,'protected_60',right,k,order) for k,right in [('old_task_accuracy','uniform_60'),('old_task_accuracy','class_balanced_60'),('rare_attack_recall','uniform_60'),('rare_attack_recall','class_balanced_60')]]
            lines.append('| '+' | '.join([env,order]+vals)+' |')
    lines+=['','The benefit does not hold uniformly in every order. In particular, federated order 1 rare recall favors uniform over protected at memory 60; order 2 rare recall slightly favors balanced over protected. Report the pooled benefit together with these exceptions.','','## 6. Excluded datasets','','The OCPP source has 163,570 nominal benign rows, but the two ZIPs are identical and its 69-column message/session schema is not compatible with the 86-field CICEVSE inputs. Independent capture grouping is unverified. The supplied CICEVSE charging/idle files duplicate the existing 14/68 rows exactly. More compatible benign traffic remains unavailable for this experiment. See `docs/research/Excluded_Datasets_Reply_2026_10_12.md` and the audit evidence.','','## Checks and limitations','','Four new allocator tests plus the original thirteen tests passed. New final models, every checkpoint prediction, source/input fingerprints, persistent roles, feasible quotas, candidate-pool limits, calibration isolation and metric arithmetic are independently checked. Consult the verification JSONs for exact counts. Sixteen benign evaluation flows remain the support; FPR at the benign-starved profile is undefined. Ten seeds quantify training randomness on one fixed split. Paired intervals are unadjusted for multiplicity. No additional datasets, new training-label merges, manuscript or submission were introduced.']
    (out/'SUPERVISOR_FOLLOWUP_SUMMARY.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    mail=['Subject: Follow-up FCL results — class-balanced baseline, joint confusion and memory sweep','','Dear Ma\'am,','','As requested, I have completed the six follow-up items. The package includes the confusion matrices, raw results, code/configurations, verification, and a summary organized by your email requests.','','The class-balanced baseline changes the interpretation. At memory 60 per federated client, old-attack type accuracy is 47.68% for class-balanced replay versus 42.78% for protected replay. However, protected replay retains higher rare-attack recall: 86.48% versus 72.09%. The protected-minus-balanced paired differences are '+interval('federated','protected_60','class_balanced_60','old_task_accuracy')+' percentage points for old accuracy and '+interval('federated','protected_60','class_balanced_60','rare_attack_recall')+' for rare recall. Centralized results show the same retention/rare-recall trade-off.','','Joint confusion matrices show recurring scan-type confusion. Joint fitting accuracy is only 57.61% federated and 60.11% centralized, close to evaluation accuracy, so the present model/training protocol also struggles on its training data. We cannot conclude that type ambiguity alone causes the low joint result. I have included family-level scoring using the pre-existing task groups alongside the type results; no training labels were merged.','','The memory sweep used 60, 120 and 300 slots per client, with matching centralized system totals of 300, 600 and 1,500. All new settings were selected on calibration data only. Federated old-accuracy / rare-recall percentages are:']
    for n in [60,120,300]:
        parts=[f'{m}: {100*value("federated",f"{m}_{n}","old_task_accuracy"):.2f} / {100*value("federated",f"{m}_{n}","rare_attack_recall"):.2f}' for m in ['uniform','class_balanced','protected']]
        mail.append(f'- Memory {n}: '+'; '.join(parts)+'.')
    mail+=['','At memory 300, protected replay retains a smaller but supported old-accuracy advantage over uniform (+1.67 points, interval 1.19–2.14). It also exceeds the original joint reference in federated old accuracy (61.75% versus 55.39%), so that reference should not be described as a demonstrated upper bound; its optimization/exposure schedule differs from continual rehearsal.','','EWC and A-GEM results and paired intervals against protected replay are included in the same four-metric format. The order-specific tables show that the benefit is not uniform across all three attack orders, so the summary records both gains and exceptions.','','Regarding the excluded data: the OCPP benign source contains 163,570 rows, but its schema and capture grouping are incompatible with the current study. The two supplied ZIPs are duplicate copies. The CICEVSE benign CSVs also duplicate existing records and add no new observations. The detailed source/compatibility audit is included; the original 16 benign evaluation examples remain the available support.','','There were 84 new calibration trials and 420 new evaluation runs; original comparison results were preserved. Seventeen relevant unit tests passed, and the verification reports cover all new models, prediction rows, splits, memory allocations and paired calculations.','','The attached/linked deliverables include the full summary and raw evidence. Please use the updated class-balanced trade-off and per-order findings when reviewing the contribution.','','Best regards,','Yuvaraj']
    (out/'SUPERVISOR_REPLY_DRAFT.txt').write_text('\n'.join(mail)+'\n',encoding='utf-8')
    print(out/'SUPERVISOR_FOLLOWUP_SUMMARY.md')

if __name__=='__main__':main()
